from mcp.server.fastmcp import FastMCP

mcp = FastMCP("notes")
NOTES = {"kafka": "Partitions give ordering per key.", "redis": "Use TTLs for cache keys."}

@mcp.tool()
def search_notes(query: str) -> list[str]:
    """Search saved notes by keyword. Returns matching note texts."""
    q = query.lower()
    return [text for title, text in NOTES.items() if q in title or q in text.lower()]

@mcp.tool()
def add_note(title: str, text: str) -> str:
    """Save a note under a short title."""
    NOTES[title.lower()] = text
    return f"Saved '{title}'"

@mcp.resource("notes://{title}")
def read_note(title: str) -> str:
    """Read one note by title."""
    return NOTES.get(title.lower(), "not found")

if __name__ == "__main__":
    mcp.run()            # stdio transport by default

