// npm install @modelcontextprotocol/sdk zod   — official TypeScript SDK
// (API names can change between SDK versions; check the SDK README.)
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { z } from 'zod';

const notes = new Map([['kafka', 'Partitions give ordering per key.']]);
const server = new McpServer({ name: 'notes', version: '1.0.0' });

server.registerTool(
  'search_notes',
  { description: 'Search saved notes by keyword.', inputSchema: { query: z.string() } },
  async ({ query }) => {
    const hits = [...notes.entries()].filter(([t, v]) => t.includes(query) || v.includes(query));
    return { content: [{ type: 'text', text: JSON.stringify(hits) }] };
  },
);

await server.connect(new StdioServerTransport());

// Same flow in Node with node-postgres (pg)
async function answer(question, { embed, pool, llm }) {
  const q = await embed(question);                 // number[]
  const { rows } = await pool.query(
    'SELECT source, content FROM chunks ORDER BY embedding <=> $1 LIMIT 5',
    [JSON.stringify(q)],
  );
  const context = rows.map((r) => `[${r.source}] ${r.content}`).join('\n\n');
  return llm(
    `Answer using ONLY these sources and cite them in [brackets].\n\n${context}\n\nQuestion: ${question}`,
  );
}

concepts.body:
**Streaming** shows progress while the graph runs:
- `stream_mode="updates"` — what each node changed, as it finishes;
- `stream_mode="messages"` — model tokens as they're generated (for chat UIs);
- `stream_mode="values"` — the full state after each step.

**When LangGraph helps:** branching flows, several tools, retries, approvals, long-running jobs, memory per thread, and the need to inspect each step.

**When it doesn't:** a single model call, or a simple tool loop of 20 lines. The plain SDK loop from the Claude API lesson is easier to read and has fewer moving parts. Also note that agent frameworks change quickly — pin versions and keep your business logic in plain functions the graph calls, so switching frameworks later is cheap.

