// npm install @langchain/langgraph @langchain/anthropic @langchain/core zod
import { MemorySaver, MessagesAnnotation, START, StateGraph } from '@langchain/langgraph';
import { ToolNode, toolsCondition } from '@langchain/langgraph/prebuilt';
import { ChatAnthropic } from '@langchain/anthropic';
import { tool } from '@langchain/core/tools';
import { z } from 'zod';

const getOrderStatus = tool(
  async ({ orderId }) => ({ A1: '3 days late' })[orderId] ?? 'not found',
  { name: 'get_order_status', description: 'Look up the delivery status of an order by its id.', schema: z.object({ orderId: z.string() }) },
);

const tools = [getOrderStatus];
const model = new ChatAnthropic({ model: 'claude-opus-5-5' }).bindTools(tools);

const graph = new StateGraph(MessagesAnnotation)
  .addNode('agent', async (state) => ({ messages: [await model.invoke(state.messages)] }))
  .addNode('tools', new ToolNode(tools))
  .addEdge(START, 'agent')
  .addConditionalEdges('agent', toolsCondition) // tool call → 'tools', else END
  .addEdge('tools', 'agent')
  .compile({ checkpointer: new MemorySaver() });

const config = { configurable: { thread_id: 'customer-42' } };
const result = await graph.invoke({ messages: [{ role: 'user', content: 'Where is order A1?' }] }, config);
console.log(result.messages.at(-1).content);

