// Reciprocal Rank Fusion + structure-aware chunking helpers
function reciprocalRankFusion(rankedLists, k = 60) {
  const scores = new Map();
  for (const ranked of rankedLists) {
    ranked.forEach((id, i) => scores.set(id, (scores.get(id) ?? 0) + 1 / (k + i + 1)));
  }
  return [...scores.entries()].sort((a, b) => b[1] - a[1]).map(([id]) => id);
}

// Split markdown by headings first, then by size, keeping the heading as metadata.
function chunkMarkdown(doc, source, maxChars = 2000) {
  const chunks = [];
  for (const section of doc.split(/\n(?=#{1,3} )/)) {
    const heading = section.match(/^#{1,3} (.*)/)?.[1] ?? '';
    for (let i = 0; i < section.length; i += maxChars - 200) {   // 200-char overlap
      chunks.push({ text: section.slice(i, i + maxChars), source, heading });
    }
  }
  return chunks;
}

console.log(reciprocalRankFusion([
