# pip install fastapi uvicorn anthropic
import json

from anthropic import AsyncAnthropic
from fastapi import FastAPI
from fastapi.responses import StreamingResponse

app = FastAPI()
client = AsyncAnthropic()                   # API key stays on the server
TOOLS = [{
    "name": "get_weather",
    "description": "Current weather for a city.",
    "input_schema": {"type": "object", "properties": {"city": {"type": "string"}}, "required": ["city"]},
}]

def run_tool(name: str, args: dict) -> dict:
    if name == "get_weather":
        return {"city": args["city"], "temp_c": 31}
    raise ValueError(f"unknown tool {name}")

def sse(event: str, data) -> str:
    return f"event: {event}\ndata: {json.dumps(data)}\n\n"

@app.post("/chat")
async def chat(body: dict):
    async def events():
        messages = body["messages"]
        try:
            for _ in range(5):                  # cap tool rounds
                async with client.messages.stream(model="claude-opus-5-5", max_tokens=4096,
                                                  tools=TOOLS, messages=messages) as stream:
                    async for event in stream:
                        if event.type == "content_block_start" and event.content_block.type == "tool_use":
                            yield sse("tool_start", {"id": event.content_block.id, "name": event.content_block.name})
                        elif event.type == "content_block_delta" and event.delta.type == "text_delta":
                            yield sse("text", {"delta": event.delta.text})
                    final = await stream.get_final_message()
                messages = messages + [{"role": "assistant", "content": final.content}]
                if final.stop_reason != "tool_use":
                    break
                results = []
                for block in final.content:
                    if block.type == "tool_use":
                        output = run_tool(block.name, block.input)
                        yield sse("tool_result", {"id": block.id, "output": output})
                        results.append({"type": "tool_result", "tool_use_id": block.id, "content": json.dumps(output)})
                messages = messages + [{"role": "user", "content": results}]
            yield sse("done", {})
        except Exception as e:                  # tell the UI instead of silently dying
            yield sse("error", {"message": str(e)})

    return StreamingResponse(events(), media_type="text/event-stream")

