// Frontend: read the SSE stream with fetch, turn events into message parts.
// parts = [{ type: 'text', text } | { type: 'tool', id, name, status: 'running' | 'done', output }]
export function applyEvent(parts, event, data) {
  switch (event) {
    case 'text': {
      const last = parts.at(-1);
      return last?.type === 'text'
        ? [...parts.slice(0, -1), { ...last, text: last.text + data.delta }]
        : [...parts, { type: 'text', text: data.delta }];
    }
    case 'tool_start':
      return [...parts, { type: 'tool', id: data.id, name: data.name, status: 'running' }];
    case 'tool_result':
      return parts.map((p) => (p.type === 'tool' && p.id === data.id ? { ...p, status: 'done', output: data.output } : p));
    case 'error':
      return [...parts, { type: 'error', text: data.message }];
    default:
      return parts;
  }
}

export async function streamChat(messages, onParts, signal) {
  const res = await fetch('/chat', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ messages }),
    signal,                                    // AbortController → Stop button
  });
  const reader = res.body.pipeThrough(new TextDecoderStream()).getReader();
  let buffer = '', parts = [];
  for (;;) {
    const { value, done } = await reader.read();
    if (done) break;
    buffer += value;
    const frames = buffer.split('\n\n');
    buffer = frames.pop();                     // keep an incomplete frame for later
    for (const frame of frames) {
      const event = frame.match(/^event: (.*)$/m)?.[1];
      const data = JSON.parse(frame.match(/^data: (.*)$/m)?.[1] ?? '{}');
      parts = applyEvent(parts, event, data);
      onParts(parts);                          // e.g. React setState
    }
  }
}

