// npm install @langchain/langgraph @langchain/anthropic @langchain/mcp-adapters
// Shorter variant: one prebuilt ReAct agent over MCP tools, with hard limits.
import { MultiServerMCPClient } from '@langchain/mcp-adapters';
import { createReactAgent } from '@langchain/langgraph/prebuilt';
import { ChatAnthropic } from '@langchain/anthropic';

const client = new MultiServerMCPClient({
  mcpServers: {
    notes: { transport: 'stdio', command: 'python', args: ['notes_server.py'] },
  },
});
const tools = await client.getTools();

const agent = createReactAgent({
  llm: new ChatAnthropic({ model: 'claude-opus-5-5' }),
  tools,
  prompt: 'First write a short numbered plan, then do each step with the tools, then give a final summary.',
});

const controller = new AbortController();
setTimeout(() => controller.abort(), 60_000);           // time budget per run

const result = await agent.invoke(
  { messages: [{ role: 'user', content: 'Summarise my Kafka notes and add a revision reminder for Friday' }] },
  { recursionLimit: 20, signal: controller.signal },    // step budget per run
);
console.log(result.messages.at(-1).content);
await client.close();
